from src.nodes.base import BaseNode
from src.runtime.assets.realization import get_asset_importer
import json

class Hou_Mcp_Asset_Import(BaseNode):
    name = "hou_mcp_asset_import"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("asset_json",   "string", widget_type="text")
        self.add_input("source_path",  "string", widget_type="text", default="")
        self.add_input("source_type",  "string", widget_type="text", default="provider")
        self.add_output("import_result_json", "string")
        self.add_output("asset_id",           "string")
        self.add_output("format_out",         "string")
        self.add_output("import_ok",          "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        asset_json  = inputs.get("asset_json", "") or ""
        source_path = str(inputs.get("source_path") or "")
        source_type = str(inputs.get("source_type") or "provider")

        if not asset_json.strip():
            self.log_error("No asset_json provided.")
            return {"import_result_json": "{}", "asset_id": "", "format_out": "", "import_ok": False, "exec_out": True}

        try:
            asset = json.loads(asset_json)
        except Exception as exc:
            self.log_error(f"Failed to parse asset_json: {exc}")
            return {"import_result_json": "{}", "asset_id": "", "format_out": "", "import_ok": False, "exec_out": True}

        try:
            result = get_asset_importer().import_asset(asset, source_path, source_type)
            self.log_info(f"Imported asset '{result.asset_name}' ({result.format}) ok={result.ok}")
            return {
                "import_result_json": json.dumps(result.to_dict(), sort_keys=True, default=str),
                "asset_id":           result.asset_id,
                "format_out":         result.format,
                "import_ok":          result.ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Asset import failed: {exc}")
            return {"import_result_json": "{}", "asset_id": "", "format_out": "", "import_ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Import
